/// <summary>
/// What a read_device request reads. Each value says which EdidioMessage payload comes back. Also used to say where an event came from.
/// </summary>
public enum ReadType {
  /// <summary>
  /// The physical inputs of one profile (profile). Reply: inputs.
  /// </summary>
  [pbr::OriginalName("INPUTS")] Inputs = 0,
  /// <summary>
  /// The outputs of one profile (profile). Reply: outputs.
  /// </summary>
  [pbr::OriginalName("OUTPUTS")] Outputs = 1,
  /// <summary>
  /// The IR codes of one profile (profile; deprecated). Reply: irs.
  /// </summary>
  [pbr::OriginalName("IR")] Ir = 2,
  /// <summary>
  /// One sensor (index) of one profile (profile). Reply: sensor.
  /// </summary>
  [pbr::OriginalName("SENSOR")] Sensor = 3,
  /// <summary>
  /// One list (index): its first 32 steps. Reply: list.
  /// </summary>
  [pbr::OriginalName("LIST")] List = 5,
  /// <summary>
  /// Every alarm. Reply: alarms.
  /// </summary>
  [pbr::OriginalName("ALARMS")] Alarms = 7,
  /// <summary>
  /// Every burn-in. Reply: burn_ins.
  /// </summary>
  [pbr::OriginalName("BURN_IN")] BurnIn = 8,
  /// <summary>
  /// Not supported - use AdminMessage SYSTEM_PROPERTIES. Reply: AckMessage (INDEX_OUT_OF_BOUNDS).
  /// </summary>
  [pbr::OriginalName("PROJECT")] Project = 9,
  /// <summary>
  /// Not supported - use AdminMessage NETWORK_PROPERTIES. Reply: AckMessage (INDEX_OUT_OF_BOUNDS).
  /// </summary>
  [pbr::OriginalName("NETWORK")] Network = 10,
  /// <summary>
  /// Not supported - use diag_message DIAGNOSTIC_SYSTEM_INFO. Reply: AckMessage (INDEX_OUT_OF_BOUNDS).
  /// </summary>
  [pbr::OriginalName("DEVICE")] Device = 11,
  /// <summary>
  /// Not supported - use diag_message DALI_LEVEL_CACHE. Reply: AckMessage (INDEX_OUT_OF_BOUNDS).
  /// </summary>
  [pbr::OriginalName("POLL_DATA")] PollData = 12,
  /// <summary>
  /// Steps beyond the first 32 of one list (index), from block secondary_index. Reply: list_extended.
  /// </summary>
  [pbr::OriginalName("LIST_EXTENDED")] ListExtended = 13,
  /// <summary>
  /// Every logic rule. Reply: logic_message.
  /// </summary>
  [pbr::OriginalName("LOGIC")] Logic = 14,
  /// <summary>
  /// The DALI inputs of one profile (profile). Reply: inputs_dali.
  /// </summary>
  [pbr::OriginalName("DALI_INPUTS")] DaliInputs = 15,
  /// <summary>
  /// Every DMX to DALI translation object. Reply: dmx_translator.
  /// </summary>
  [pbr::OriginalName("DMX_TRANSLATIONS")] DmxTranslations = 16,
}

/// <summary>
/// Whether an alarm repeats. Which days it runs on comes from repeat_day_bitmask and repeat_month_bitmask.
/// </summary>
public enum AlarmRepeatType {
  /// <summary>
  /// Once, on the date in start_time
  /// </summary>
  [pbr::OriginalName("ALARM_NO_REPEAT")] AlarmNoRepeat = 0,
  /// <summary>
  /// Repeats - on the weekdays in repeat_day_bitmask and months in repeat_month_bitmask (set all days)
  /// </summary>
  [pbr::OriginalName("ALARM_REPEAT_DAILY")] AlarmRepeatDaily = 1,
  /// <summary>
  /// Repeats - on the weekdays in repeat_day_bitmask (set Monday to Friday)
  /// </summary>
  [pbr::OriginalName("ALARM_REPEAT_WORK_DAY")] AlarmRepeatWorkDay = 2,
  /// <summary>
  /// Repeats - on the weekday(s) in repeat_day_bitmask
  /// </summary>
  [pbr::OriginalName("ALARM_REPEAT_WEEKLY")] AlarmRepeatWeekly = 3,
  /// <summary>
  /// Repeats - in the months in repeat_month_bitmask. The firmware treats every type but NO_REPEAT alike: the bitmasks decide
  /// </summary>
  [pbr::OriginalName("ALARM_REPEAT_MONTHLY")] AlarmRepeatMonthly = 4,
}

/// <summary>
/// Whether an alarm's start or end is a clock time, or sunrise / sunset with the time as an offset.
/// </summary>
public enum AlarmAstroType {
  /// <summary>
  /// At the clock time given
  /// </summary>
  [pbr::OriginalName("ALARM_NO_ASTRO")] AlarmNoAstro = 0,
  /// <summary>
  /// At sunrise (from LATITUDE / LONGITUDE), moved by the time given as an offset
  /// </summary>
  [pbr::OriginalName("ALARM_SUNRISE")] AlarmSunrise = 1,
  /// <summary>
  /// At sunset, moved by the time given as an offset
  /// </summary>
  [pbr::OriginalName("ALARM_SUNSET")] AlarmSunset = 2,
}

