/// <summary>
/// What an EventMessage reports. On an eDIDIO, live events are EventStreamMessage (event_stream).
/// </summary>
public enum EventType {
  /// <summary>
  /// Sent by the client to register for events.
  /// </summary>
  [pbr::OriginalName("REGISTER")] Register = 0,
  /// <summary>
  /// Emitted when trigger runs an action listed in TriggerType.
  /// </summary>
  [pbr::OriginalName("TRIGGER_EVENT")] TriggerEvent = 1,
  /// <summary>
  /// Emitted when a physical Input is triggered.
  /// </summary>
  [pbr::OriginalName("INPUT_EVENT")] InputEvent = 2,
  /// <summary>
  /// Emitted when a Sensor (24-bit DALI or 25-bit) is triggered.
  /// </summary>
  [pbr::OriginalName("SENSOR_EVENT")] SensorEvent = 3,
  /// <summary>
  /// Emitted when a DALI/DMX/physical output type event is done. References an action in TriggerType.
  /// </summary>
  [pbr::OriginalName("CONTROL_EVENT")] ControlEvent = 4,
  /// <summary>
  /// Emitted when rooms are joined/unjoined.
  /// </summary>
  [pbr::OriginalName("ROOM_JOIN_EVENT")] RoomJoinEvent = 5,
  /// <summary>
  /// Emitted when a 24-bit DALI Input Device is triggered.
  /// </summary>
  [pbr::OriginalName("DALI_24_INPUT_EVENT")] Dali24InputEvent = 6,
  /// <summary>
  /// Emitted when a 24-bit DALI Frame is received.
  /// </summary>
  [pbr::OriginalName("DALI_24_FRAME_EVENT")] Dali24FrameEvent = 7,
}

