  [pbr::OriginalName("DALI_QUERY_MULTI_TYPES")] DaliQueryMultiTypes = 6,
}

/// <summary>
/// The property an AdminMessage targets. Each value lists its commands, the AdminMessage field its value travels in (Payload), and the login role it needs.
/// </summary>
public enum AdminPropertyType {
  /// <summary>
  /// The device name that appears on the network. Limited to 16 characters. Commands: GET, SET. Payload: data.string_data. Role: CONFIG. Devices: eDIDIO, ADDICT.
  /// </summary>
  [pbr::OriginalName("DEVICE_NAME")] DeviceName = 0,
  /// <summary>
