  /// </summary>
  [pbr::OriginalName("SET")] Set = 0,
  /// <summary>
  /// Get property
  /// </summary>
  [pbr::OriginalName("GET")] Get = 1,
  /// <summary>
  /// Add property
  /// </summary>
  [pbr::OriginalName("ADD")] Add = 2,
  /// <summary>
  /// Remove property
  /// </summary>
  [pbr::OriginalName("REMOVE")] Remove = 3,
  /// <summary>
  /// Reset property
  /// </summary>
  [pbr::OriginalName("RESET")] Reset = 4,
  /// <summary>
  /// Run property
  /// </summary>
  [pbr::OriginalName("RUN")] Run = 5,
}

/// <summary>
/// DALI status query response bitmask values - See DALI Standard
/// IEC 62386-102 control-GEAR status byte (reply to the 16-bit QUERY STATUS, for lamps/drivers).
/// NOTE: this is NOT the IEC 62386-103 control-DEVICE deviceStatus (reply to the 24-bit QUERY DEVICE STATUS
/// used for input devices/sensors). For a SENSOR power cycle, powerCycleSeen is deviceStatus bit5 (0x20), not
/// the bit7 (=128) below.
/// </summary>
public enum DALIStatusType {
  /// <summary>
  /// Not technically in DALI. But this is the default when mask = 0b00000000
  /// </summary>
  [pbr::OriginalName("LAMP_OFF")] LampOff = 0,
  /// <summary>
  /// Bit 0: control gear failure
  /// </summary>
  [pbr::OriginalName("CONTROL_GEAR_FAILURE")] ControlGearFailure = 1,
  /// <summary>
  /// Bit 1: lamp failure
  /// </summary>
  [pbr::OriginalName("LAMP_FAILURE")] LampFailure = 2,
  /// <summary>
  /// Bit 2: lamp on (arc power above 0)
  /// </summary>
  [pbr::OriginalName("LAMP_ON")] LampOn = 4,
  /// <summary>
  /// Bit 3: limit error - the last level asked for was outside min / max
  /// </summary>
  [pbr::OriginalName("LIMIT_ERROR")] LimitError = 8,
  /// <summary>
  /// Bit 4: a fade is running
  /// </summary>
  [pbr::OriginalName("FADE_RUNNING")] FadeRunning = 16,
  /// <summary>
  /// Bit 5: in the reset state
  /// </summary>
  [pbr::OriginalName("RESET_STATE")] ResetState = 32,
  /// <summary>
  /// Bit 6: short address is MASK (no short address)
  /// </summary>
  [pbr::OriginalName("SHORT_ADDRESS")] ShortAddress = 64,
  /// <summary>
  /// Bit 7: power cycle seen since the last reset
  /// </summary>
  [pbr::OriginalName("POWER_CYCLE_SEEN")] PowerCycleSeen = 128,
}

/// <summary>
/// DALI Receive Flag 
/// </summary>
public enum DALIRXStatusFlag {
  /// <summary>
  /// Internal Idle State - Should not be received
  /// </summary>
  [pbr::OriginalName("WAITING")] Waiting = 0,
  /// <summary>
  /// DALI Frame being Received
  /// </summary>
  [pbr::OriginalName("RECEIVING_FRAME")] ReceivingFrame = 1,
  /// <summary>
  /// Frame was recorded - Empty Data
  /// </summary>
  [pbr::OriginalName("NO_RECEIVED_FRAME")] NoReceivedFrame = 2,
  /// <summary>
  /// Frame was recorded - 8 Bit Reply
  /// </summary>
  [pbr::OriginalName("RECEIVED_8_BIT_FRAME")] Received8BitFrame = 3,
  /// <summary>
  /// Frame was recorded - 16 Bit - Standard Message
  /// </summary>
  [pbr::OriginalName("RECEIVED_16_BIT_FRAME")] Received16BitFrame = 4,
  /// <summary>
  /// Frame was recorded - 24 Bit - eDALI Message
  /// </summary>
  [pbr::OriginalName("RECEIVED_24_BIT_FRAME")] Received24BitFrame = 5,
  /// <summary>
  /// Frame was recorded - Unusual Bit count
  /// </summary>
  [pbr::OriginalName("RECEIVED_PARTIAL_FRAME")] ReceivedPartialFrame = 6,
  /// <summary>
  /// DALI System Idle
  /// </summary>
  [pbr::OriginalName("IDLE")] Idle = 7,
  /// <summary>
  /// Inhouse DALI Calibration
  /// </summary>
  [pbr::OriginalName("CALIBRATION")] Calibration = 8,
  /// <summary>
  /// Error while trying to Transmit DALI - Possibly no Bus Power
  /// </summary>
  [pbr::OriginalName("ERROR_WHILE_SENDING")] ErrorWhileSending = 254,
  /// <summary>
  /// Error while trying to Receive - Invalid Frame Data, or no response
  /// </summary>
  [pbr::OriginalName("ERROR_WHILE_RECEIVING")] ErrorWhileReceiving = 255,
}

/// <summary>
/// Which report a diag_message asks for. Each value says what comes back.
/// </summary>
public enum DiagnosticMessageType {
  /// <summary>
  /// Can be used to retrieve a large number of properties that describe the capabilities of the device. (Number of supported Lists, Alarms, etc.). Reply: diag_system. Devices: eDIDIO, ADDICT.
  /// </summary>
  [pbr::OriginalName("DIAGNOSTIC_SYSTEM_INFO")] DiagnosticSystemInfo = 0,
  /// <summary>
  /// Not currently supported (will default to SYSTEM_INFO). Reply: diag_system. Devices: eDIDIO, ADDICT.
  /// </summary>
  [pbr::OriginalName("DIAGNOSTIC_INPUT_STATUS")] DiagnosticInputStatus = 1,
  /// <summary>
  /// Can be used to retrieve the current entries of the in-memory DALI values cache. Reply: level_cache_response (64 levels of line).
  /// </summary>
  [pbr::OriginalName("DALI_LEVEL_CACHE")] DaliLevelCache = 2,
  /// <summary>
  /// Can be used to retrieve the current entries of the in-memory DMX levels cache. Results must be paginated due to size of DMX universe (512). Reply: level_cache_response (64 levels of line, from page x 64). Devices: eDIDIO, ADDICT.
  /// </summary>
  [pbr::OriginalName("DMX_LEVEL_CACHE")] DmxLevelCache = 3,
  /// <summary>
  /// Removed: the "Joined Rooms" state no longer exists. Reply: AckMessage (INDEX_OUT_OF_BOUNDS).
  /// </summary>
  [pbr::OriginalName("ROOM_JOINS")] RoomJoins = 4,
  /// <summary>
  /// Can be used to retrieve the current entries of the in-memory DALI status cache. Reply: level_cache_response (64 status bytes of line).
  /// </summary>
  [pbr::OriginalName("DALI_STATUS_CACHE")] DaliStatusCache = 5,
}

/// <summary>
/// The steps of a firmware update (FirmwareControlMessage), both directions.
/// </summary>
public enum FirmwareCommandType {
  /// <summary>
  /// System Ready for Firmware Message
  /// </summary>
  [pbr::OriginalName("FW_READY")] FwReady = 0,
  /// <summary>
  /// Sent to controller to initiate a Firmware update
  /// </summary>
  [pbr::OriginalName("FW_APPLY")] FwApply = 1,
  /// <summary>
  /// Sent to controller to initiate stored Firmware verification - This will complete the firmware upload mode and unlock normal functionality. 
  /// </summary>
  [pbr::OriginalName("FW_VERIFY")] FwVerify = 2,
  /// <summary>
  /// Received from controller - Issue with stored Firmware
  /// </summary>
  [pbr::OriginalName("FW_VERIFY_FAILED")] FwVerifyFailed = 3,
  /// <summary>
  /// Received from controller - Stored Firmware is Valid
  /// </summary>
  [pbr::OriginalName("FW_VERIFY_SUCCESS")] FwVerifySuccess = 4,
  /// <summary>
  /// Sent to controller to request information for currently stored Firmware
  /// </summary>
  [pbr::OriginalName("FW_READ")] FwRead = 5,
  /// <summary>
  /// Command to Clone Main FW to Backup. Using the firmware_is_backup flag will clone Backup to Main
  /// </summary>
  [pbr::OriginalName("FW_CLONE")] FwClone = 6,
}

/// <summary>
/// How a sequence moves from one colour to the next.
/// </summary>
public enum SpektraTransitionType {
  /// <summary>
  /// Blended colour transitions. Example: Transition between red and green will go through yellow.
  /// </summary>
  [pbr::OriginalName("BLEND")] Blend = 0,
  /// <summary>
  /// Instant colour transitions.
  /// </summary>
  [pbr::OriginalName("SNAP")] Snap = 1,
  /// <summary>
  /// Example: Transition between red and green will fade the light off then on between colours. Not currently supported.
  /// </summary>
  [pbr::OriginalName("FADE_TO_BLACK")] FadeToBlack = 2,
}

/// <summary>
/// Types of conditions that can be evaluated in Logic rules
/// </summary>
public enum LogicType {
  /// <summary>
  /// Compare against a DALI device's arc level (0-254)
  /// </summary>
  [pbr::OriginalName("DALI_LEVEL")] DaliLevel = 0,
  /// <summary>
  /// Compare against a physical input's current state (HIGH/LOW)
  /// </summary>
  [pbr::OriginalName("INPUT_STATE")] InputState = 1,
  /// <summary>
  /// Check if a specific List is currently running
  /// </summary>
  [pbr::OriginalName("LIST_RUNNING")] ListRunning = 2,
  /// <summary>
  /// Check if a sensor has detected occupancy
  /// </summary>
  [pbr::OriginalName("OCCUPANCY_DETECTED")] OccupancyDetected = 3,
  /// <summary>
  /// Check if DMX input signal is being received
  /// </summary>
  [pbr::OriginalName("DMX_PRESENT")] DmxPresent = 4,
  /// <summary>
  /// Compare against current day of week (1=Monday to 7=Sunday)
  /// </summary>
  [pbr::OriginalName("CAL_WEEKDAY")] CalWeekday = 5,
  /// <summary>
  /// Compare against current month (1=January to 12=December)
  /// </summary>
  [pbr::OriginalName("CAL_MONTH")] CalMonth = 6,
  /// <summary>
  /// Check if a specific alarm/schedule is active
  /// </summary>
  [pbr::OriginalName("ALARM_SCHEDULED")] AlarmScheduled = 7,
  /// <summary>
  /// Checks if any DALI device in the cache has an error status
  /// </summary>
  [pbr::OriginalName("DALI_CACHE_STATUS")] DaliCacheStatus = 8,
  /// <summary>
  /// Check device error flags. target_index is bitmask: [bit0=DALI Poll Error, bit1=DALI Line Error, bit2=Ethernet Link Dropped, bit3=Over Temperature, bit4=OLED Error, bits5-7=Reserved]
  /// </summary>
  [pbr::OriginalName("HAS_ERROR")] HasError = 9,
}

/// <summary>
/// How a logic rule compares its variable with comparison_value. It runs trigger A when the comparison holds, else trigger B.
/// </summary>
public enum LogicComparisonType {
  /// <summary>
  /// A runs if the variable &lt; comparison_value, else B
  /// </summary>
  [pbr::OriginalName("LESS_THAN")] LessThan = 0,
  /// <summary>
  /// A runs if the variable &lt;= comparison_value, else B
  /// </summary>
  [pbr::OriginalName("LESS_THAN_OR_EQUALS")] LessThanOrEquals = 1,
  /// <summary>
  /// A runs if the variable == comparison_value, else B
  /// </summary>
  [pbr::OriginalName("EQUALS")] Equals = 2,
  /// <summary>
  /// A runs if the variable > comparison_value, else B
  /// </summary>
  [pbr::OriginalName("MORE_THAN")] MoreThan = 3,
  /// <summary>
  /// A runs if the variable >= comparison_value, else B
  /// </summary>
  [pbr::OriginalName("MORE_THAN_OR_EQUALS")] MoreThanOrEquals = 4,
  /// <summary>
  /// A runs if the variable != comparison_value, else B
  /// </summary>
  [pbr::OriginalName("NOT_EQUAL")] NotEqual = 5,
  /// <summary>
  /// A runs if (variable | comparison_value) is non-zero, else B
  /// </summary>
  [pbr::OriginalName("BIT_OR")] BitOr = 6,
  /// <summary>
  /// A runs if (variable &amp; comparison_value) is non-zero - any of the masked bits set - else B
  /// </summary>
  [pbr::OriginalName("BIT_AND")] BitAnd = 7,
  /// <summary>
  /// A runs if (variable ^ comparison_value) is non-zero - they differ - else B
  /// </summary>
  [pbr::OriginalName("BIT_XOR")] BitXor = 8,
}

