/// <summary>
/// The result of an SD card operation.
/// </summary>
public enum SdStatusCode {
  /// <summary>
  /// Success
  /// </summary>
  [pbr::OriginalName("SD_OK")] SdOk = 0,
  /// <summary>
  /// No card, or it is not mounted
  /// </summary>
  [pbr::OriginalName("SD_NOT_MOUNTED")] SdNotMounted = 1,
  /// <summary>
  /// No such file
  /// </summary>
  [pbr::OriginalName("SD_FILE_NOT_FOUND")] SdFileNotFound = 2,
  /// <summary>
  /// Not allowed (e.g. delete, until enabled)
  /// </summary>
  [pbr::OriginalName("SD_ACCESS_DENIED")] SdAccessDenied = 3,
  /// <summary>
  /// The card is full
  /// </summary>
  [pbr::OriginalName("SD_DISK_FULL")] SdDiskFull = 4,
  /// <summary>
  /// The card returned an error
  /// </summary>
  [pbr::OriginalName("SD_IO_ERROR")] SdIoError = 5,
  /// <summary>
  /// The path is not valid
  /// </summary>
  [pbr::OriginalName("SD_INVALID_PATH")] SdInvalidPath = 6,
  /// <summary>
  /// The card is in use - retry
  /// </summary>
  [pbr::OriginalName("SD_BUSY")] SdBusy = 7,
  /// <summary>
  /// The card did not answer in time
  /// </summary>
  [pbr::OriginalName("SD_TIMEOUT")] SdTimeout = 8,
  /// <summary>
  /// A write failed
  /// </summary>
  [pbr::OriginalName("SD_WRITE_ERROR")] SdWriteError = 9,
  /// <summary>
  /// The volume is mounted but its capacity has never been measured: every
  /// f_getfree() since the mount failed. Returned by SD_GET_SPACE instead of an
  /// SD_OK carrying free_bytes = total_bytes = 0, which is indistinguishable
  /// from a card with nothing left on it. A client seeing this should treat
  /// free space as unknown, not as zero.
  /// </summary>
  [pbr::OriginalName("SD_CAPACITY_UNKNOWN")] SdCapacityUnknown = 10,
  /// <summary>
  /// The operation was abandoned by the device's own per-operation deadline
  /// rather than failing on the media. Distinguishes a card that is too slow
  /// (or a bus that stalled) from one that is returning errors: the request
  /// may well succeed on a retry, where SD_IO_ERROR usually will not.
  /// </summary>
  [pbr::OriginalName("SD_DEADLINE_ABORT")] SdDeadlineAbort = 11,
}

